fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let colw: i32 = w / 16;
    let mut arr = [0; 16];
    let mut i: i32 = 0;
    while i < 16 {
        arr[i] = host::display::state_get(8 + i);
        i = i + 1;
    }
    let mut pour: i32 = host::display::pointer_x() / colw;
    if pour < 0 { pour = 0; }
    if pour > 15 { pour = 15; }
    if t % 3 == 0 {
        arr[pour] = arr[pour] + 1;
    }
    let mut pass: i32 = 0;
    while pass < 6 {
        i = 0;
        while i < 16 {
            if i < 15 && arr[i] > arr[i + 1] + 2 {
                arr[i] = arr[i] - 1;
                arr[i + 1] = arr[i + 1] + 1;
            }
            if i > 0 && arr[i] > arr[i - 1] + 2 {
                arr[i] = arr[i] - 1;
                arr[i - 1] = arr[i - 1] + 1;
            }
            i = i + 1;
        }
        pass = pass + 1;
    }
    let mut top: i32 = 0;
    i = 0;
    while i < 16 {
        if arr[i] > top { top = arr[i]; }
        i = i + 1;
    }
    if top * 4 > h - 40 {
        i = 0;
        while i < 16 {
            if arr[i] > 0 { arr[i] = arr[i] - 1; }
            i = i + 1;
        }
    }
    i = 0;
    while i < 16 {
        host::display::state_set(8 + i, arr[i]);
        i = i + 1;
    }
    host::display::clear(0x14100c);
    i = 0;
    while i < 16 {
        let ch: i32 = arr[i] * 4;
        host::display::fill_rect(i * colw, h - ch, colw - 1, ch, 0xc8a050);
        i = i + 1;
    }
    host::display::fill_rect(pour * colw + colw / 2 - 3, 10, 6, 10, 0xf0e0b0);
    host::display::draw_string(8, 30, "POINT TO POUR", 0x707070, 1);
    host::display::present();
}
